import{_ as a,c as l,o as i,ag as r}from"./chunks/framework.C86mscM5.js";const p=JSON.parse('{"title":"DevOps","description":"","frontmatter":{},"headers":[],"relativePath":"devops/index.md","filePath":"devops/index.md","lastUpdated":1788092044000}'),t={name:"devops/index.md"};function o(n,e,h,d,s,c){return i(),l("div",null,e[0]||(e[0]=[r('<h1 id="devops" tabindex="-1">DevOps <a class="header-anchor" href="#devops" aria-label="Permalink to &quot;DevOps&quot;">​</a></h1><p>DevOps 关注的是让软件从代码变更到生产运行形成一条可重复、可观测、可恢复的交付链路。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><p>一条完整链路通常包含计划、编码、验证、构建、制品存储、发布、部署、运行、观测和反馈。工具不是目标，缩短反馈时间、降低变更风险并提高恢复能力才是目标。</p><h2 id="基本原则" tabindex="-1">基本原则 <a class="header-anchor" href="#基本原则" aria-label="Permalink to &quot;基本原则&quot;">​</a></h2><ul><li>所有生产变更都可追溯到版本控制中的代码、配置或审批记录。</li><li>同一制品在环境之间晋级，不为测试和生产分别重新构建。</li><li>自动化任务应可重复执行，失败后能够安全重试。</li><li>发布前定义验证方式和回滚条件，发布后立即验证用户可感知结果。</li><li>不以“装了某个工具”代替流程、权限和责任边界。</li></ul><h2 id="环境模型" tabindex="-1">环境模型 <a class="header-anchor" href="#环境模型" aria-label="Permalink to &quot;环境模型&quot;">​</a></h2><p>常见环境包括本地开发、集成测试、预发布和生产。环境数量不是越多越好，每套环境都应有明确用途、责任人、数据策略和退出条件。</p><h2 id="配置原则" tabindex="-1">配置原则 <a class="header-anchor" href="#配置原则" aria-label="Permalink to &quot;配置原则&quot;">​</a></h2><ul><li>代码与环境配置分离；配置结构随代码版本管理，敏感值进入 Secret 系统。</li><li>使用明确的配置契约，在启动阶段校验必填项、类型和取值范围。</li><li>避免在镜像或前端静态文件中写入运行时 Secret。</li><li>前端可公开配置应在构建期或运行期明确注入，并视为用户可见数据。</li><li>记录配置变更，确保能够比较环境差异并回滚。</li></ul><h2 id="环境晋级" tabindex="-1">环境晋级 <a class="header-anchor" href="#环境晋级" aria-label="Permalink to &quot;环境晋级&quot;">​</a></h2><p>生产发布应使用已经通过测试的同一制品，通过环境级配置改变连接地址、容量或功能开关。禁止在服务器上手工修改构建产物。</p><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><ul><li>环境命名、入口和所有者是否明确？</li><li>Secret 是否会进入日志、源码、镜像层或浏览器？</li><li>配置错误能否在部署验证阶段被快速发现？</li><li>配置与制品是否都有版本和审计记录？</li></ul><p>制品是流水线生成并交付的不可变输出，例如静态资源压缩包、npm 包、二进制文件或 OCI 镜像。</p><h2 id="推荐流程" tabindex="-1">推荐流程 <a class="header-anchor" href="#推荐流程" aria-label="Permalink to &quot;推荐流程&quot;">​</a></h2><ol><li>CI 根据 Commit 构建一次制品，并记录版本、Commit SHA 和构建信息。</li><li>完成测试、SBOM 生成、漏洞扫描和签名。</li><li>将制品上传到有保留策略的仓库。</li><li>测试、预发布和生产引用同一摘要或版本。</li><li>部署记录保存“环境—制品版本—配置版本”的对应关系。</li></ol><h2 id="版本策略" tabindex="-1">版本策略 <a class="header-anchor" href="#版本策略" aria-label="Permalink to &quot;版本策略&quot;">​</a></h2><ul><li>人类发布版本使用 SemVer 或业务版本号。</li><li>自动构建保留 Commit SHA，便于追溯。</li><li>容器生产部署优先使用 digest；可读标签只作为辅助。</li><li>禁止覆盖已经发布的生产版本。</li></ul><h2 id="回滚" tabindex="-1">回滚 <a class="header-anchor" href="#回滚" aria-label="Permalink to &quot;回滚&quot;">​</a></h2><p>回滚应重新部署上一个已验证制品，而不是重新构建旧代码。数据库变更应采用向前兼容、分阶段迁移或单独恢复策略。</p><h2 id="三条实践链路" tabindex="-1">三条实践链路 <a class="header-anchor" href="#三条实践链路" aria-label="Permalink to &quot;三条实践链路&quot;">​</a></h2><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><p><code>提交 → Lint/测试 → 构建静态资源 → 发布 CDN/托管平台 → RUM → 回滚</code></p><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><p><code>提交 → 测试 → 构建镜像 → 生成 SBOM/扫描 → 推送 Harbor → 部署 → APM/日志 → 回滚</code></p><h3 id="kubernetes" tabindex="-1">Kubernetes <a class="header-anchor" href="#kubernetes" aria-label="Permalink to &quot;Kubernetes&quot;">​</a></h3><p><code>配置与 Secret → Helm/Kustomize → Workload/Service → Gateway/TLS → 探针与扩缩容 → 告警与排障</code></p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://landscape.cncf.io/" target="_blank" rel="nofollow noopener noreferrer">CNCF Cloud Native Landscape</a></li><li><a href="https://www.youtube.com/@TechWorldwithNana" target="_blank" rel="nofollow noopener noreferrer">TechWorld with Nana</a></li></ul>',30)]))}const b=a(t,[["render",o]]);export{p as __pageData,b as default};
